with matched as (select e.*, sub.id as subscription_id, sub.plan, sub.monthly_fee from sessions e left join subscriptions sub on e.customer_id = sub.customer_id and e.started_at >= sub.start_date and e.started_at < sub.end_date + interval '7' day), kept as (select s.* from matched s where not exists (select 1 from web_events x where x.session_id = s.id and x.event_time >= s.started_at)), metrics as (select *, avg(subscription_id) over (partition by country order by subscription_id, id, subscription_id rows between 2 preceding and current row) as subscription_id_avg_2, cume_dist() over (partition by customer_id, plan order by monthly_fee desc nulls last) as monthly_fee_cume_dist, sum(monthly_fee) over (order by started_at, id, subscription_id rows between unbounded preceding and current row) as running_monthly_fee from kept) select id, customer_id, device, browser, started_at, country, subscription_id, monthly_fee, subscription_id_avg_2, case when device rlike '^(desktop|tablet)$' then 'CORE' else 'GROUP_B' end as device_zone from metrics
